<script setup lang="ts">
/**
 * The command palette (`design/components/command.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/dialog'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  focusPlace,
  focusReturnTarget,
  useDirection,
  type IconRole,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/command.module.css'
import CommandPanel from './CommandPanel.vue'

export interface CommandItem {
  id: string
  label: string
  icon?: IconRole
  hint?: string
  group?: string
  keywords?: string[]
  disabled?: boolean
  onSelect: () => void
}

export interface CommandProps {
  /**
   * `false` for chained palettes, where the query stays after a command runs.
   */
  closeOnSelect?: boolean
  emptyMessage?: string
  /**
   * The dismiss key label beside the search field (default `esc`). Hosts localize it because a
   * key legend is text too.
   */
  escapeHint?: string
  /**
   * `false` when the app filters the items itself, as with async command sources.
   */
  filter?: false | 'contains'
  items: CommandItem[]
  /**
   * The dialog's accessible name; localized hosts replace the default `Command palette`.
   */
  label?: string
  loading?: boolean
  /**
   * The app owns the ⌘K binding, because a global hotkey is app policy, not vocabulary.
   */
  open: boolean
  placeholder?: string
}

defineOptions({ name: 'Command', inheritAttrs: false })

const props = withDefaults(defineProps<CommandProps>(), {
  closeOnSelect: true,
  emptyMessage: 'No results',
  escapeHint: 'esc',
  filter: 'contains',
  label: 'Command palette',
  loading: false,
  placeholder: 'Type a command…',
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
const uid = useId()
const query = ref('')
const returnTo = ref(null as ReturnType<typeof focusPlace>)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    finalFocusEl: () => focusReturnTarget(returnTo.value, [panel.value]),
    'aria-label': props.label,
    onEscapeKeyDown: (event) => query.value !== '' && event.preventDefault(),
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const scrimPresent = usePresence(() => api.value.open, scrim, 'dialog.scrim')
const panelPresent = usePresence(() => api.value.open, panel, 'command.panel', {
  side: 'bottom',
  align: 'center',
})
const effect1 = () => {
  api.value.open && (returnTo.value = focusPlace(document.activeElement))
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Command',
    element: () => panel.value,
    state: () => ({
      open: api.value.open,
      items: props.items.map((item) => ({
        id: item.id,
        label: item.label,
        ...(item.disabled === true ? { disabled: true } : {}),
      })),
      query: api.value.open ? query.value : '',
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => (
          props.items.find((item) => item.id === value)?.onSelect(),
          api.value.open && props.closeOnSelect && api.value.setOpen(false)
        ),
      },
      close: () => api.value.open && api.value.setOpen(false),
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <Teleport to="body">
    <!-- scrim -->
    <div
      v-if="scrimPresent"
      ref="scrim"
      v-bind="api.getBackdropProps()"
      :class="styles.scrim"
      :hidden="undefined"
    />
    <div v-if="panelPresent" v-bind="api.getPositionerProps()" :class="styles.positioner">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :hidden="undefined"
        :aria-describedby="undefined"
        :data-loading="loading ? '' : undefined"
        data-member="command"
      >
        <CommandPanel
          :items="items"
          :placeholder="placeholder"
          :escapeHint="escapeHint"
          :filter="filter"
          :loading="loading"
          :emptyMessage="emptyMessage"
          @queryChange="query = $event"
          @command="closeOnSelect && api.setOpen(false)"
        />
      </div>
    </div>
  </Teleport>
</template>
